// dsh-anim-pack / lib/fx.js
//
// Pure, host-free logic over the mirrored patch-gg/pixelfx repository (the
// 244 code-driven pixel-art effects). The catalog under assets/fx/ is a
// snapshot generated by tools/build-fx.mjs: the host never imports an effect
// module, it only reads JSON, source text and pre-rendered previews.
//
// No cordis / DSH imports here on purpose: tools/verify.mjs exercises this
// file directly with plain node.

import { copyFileSync, existsSync, mkdirSync, readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs'
import { basename, dirname, join, resolve, sep } from 'node:path'

import { clampLimit } from './catalog.js'

/** Where the generated effect catalog lives inside the plugin root. */
export const FX_CATALOG_REL = join('assets', 'fx', 'catalog.json')

/** Everything a free-text search may look at, folded once. */
const fold = (text) => String(text ?? '').toLowerCase()

function haystack(entry) {
  return fold([
    entry.id,
    entry.name,
    entry.category,
    entry.categoryName,
    entry.desc,
    ...(Array.isArray(entry.tags) ? entry.tags : []),
  ].join(' '))
}

/**
 * Load and normalise the effect catalog.
 * Stored paths stay relative; absolute `filePath` / `previewPath` are added
 * next to them so the host side never has to join paths itself.
 * `repo` overrides the mirror path recorded at build time (config `fxPath`).
 */
export function loadFxCatalog(root, { repo: repoOverride = '' } = {}) {
  const base = resolve(root)
  const catalogPath = join(base, FX_CATALOG_REL)
  let data
  try {
    data = JSON.parse(readFileSync(catalogPath, 'utf8'))
  } catch (error) {
    throw new Error(`cannot read effect catalog at ${catalogPath}: ${error?.message ?? error}`)
  }
  // 索引里记的是相对插件根的路径（可移植）；老索引里的绝对路径也认。
  // fxPath 配置优先，其次按记录值解析：相对 → 相对 base，绝对 → 原样。
  // 记录值指不到东西时再试插件根下的 pixelfx/（本仓库单独 clone 时的常规摆放）。
  const stored = typeof data.repo === 'string' ? data.repo : ''
  const recorded = stored ? resolve(base, stored) : ''
  const nested = join(base, 'pixelfx')
  const repo = repoOverride
    ? resolve(repoOverride)
    : recorded && existsSync(join(recorded, 'src', 'fx'))
      ? recorded
      : existsSync(join(nested, 'src', 'fx'))
        ? nested
        : recorded
  const entries = (Array.isArray(data.entries) ? data.entries : []).map((entry) => ({
    ...entry,
    tags: Array.isArray(entry.tags) ? entry.tags : [],
    size: Array.isArray(entry.size) ? entry.size : [0, 0],
    origin: Array.isArray(entry.origin) ? entry.origin : [0, 0],
    options: entry.options && typeof entry.options === 'object' ? entry.options : {},
    filePath: entry.file && repo ? join(repo, entry.file) : '',
    libPath: entry.file && entry.lib && repo ? join(repo, dirname(entry.file), entry.lib) : '',
    previewPath: entry.preview ? join(base, 'assets', 'fx', entry.preview) : '',
  }))
  const byId = new Map(entries.map((entry) => [fold(entry.id), entry]))
  const byName = new Map()
  const bySlug = new Map()
  for (const entry of entries) {
    const name = fold(entry.name)
    const slug = fold(entry.id.split('/').pop() ?? '')
    if (!byName.has(name)) byName.set(name, [])
    byName.get(name).push(entry)
    if (!bySlug.has(slug)) bySlug.set(slug, [])
    bySlug.get(slug).push(entry)
  }
  const categories = (Array.isArray(data.categories) ? data.categories : []).map((row) => ({
    id: row.id,
    name: row.name ?? row.id,
    blurb: row.blurb ?? '',
    count: Number(row.count ?? 0),
  }))
  return {
    root: base,
    catalogPath,
    repo,
    commit: String(data.commit ?? ''),
    commitShort: String(data.commitShort ?? ''),
    upstream: String(data.upstream ?? ''),
    generated: String(data.generated ?? ''),
    version: String(data.version ?? ''),
    license: String(data.license ?? ''),
    total: Number.isFinite(data.total) ? data.total : entries.length,
    categories,
    entries,
    byId,
    byName,
    bySlug,
  }
}

/**
 * Look an effect up by id ("fire/torch"), by bare name ("torch") or by bare
 * file name, case-insensitively. An ambiguous bare name comes back as
 * `ambiguous` with its candidates instead of silently picking one.
 */
export function resolveFx(catalog, value) {
  const raw = String(value ?? '').trim().replace(/\.js$/i, '')
  const key = fold(raw)
  if (!key) return { kind: 'missing', entry: null, candidates: [] }
  const direct = catalog.byId.get(key)
  if (direct) return { kind: 'exact', entry: direct, candidates: [] }
  for (const map of [catalog.byName, catalog.bySlug]) {
    const hits = map.get(key) ?? []
    if (hits.length === 1) return { kind: 'loose', entry: hits[0], candidates: [] }
    if (hits.length > 1) return { kind: 'ambiguous', entry: null, candidates: hits }
  }
  return { kind: 'missing', entry: null, candidates: [] }
}

/** Backwards-friendly shortcut: the entry, or null. */
export function getFx(catalog, value) {
  return resolveFx(catalog, value).entry
}

/** Compact row used by search / random / category listings. */
export function summarizeFx(entry) {
  return {
    id: entry.id,
    name: entry.name,
    category: entry.category,
    tags: entry.tags.slice(0, 6),
    size: entry.size,
    duration: entry.duration,
    fps: entry.fps,
    loop: Boolean(entry.loop),
    actor: Boolean(entry.actor),
    acted: Boolean(entry.act),
    hasPreview: Boolean(entry.previewPath && existsSync(entry.previewPath)),
    desc: entry.desc,
  }
}

/** `loop`: 'any' | 'loop' | 'once'. */
function loopWanted(value) {
  const v = fold(value).trim()
  if (['loop', 'loops', 'looping', '循环'].includes(v)) return true
  if (['once', 'one-shot', 'oneshot', 'shot', '单次'].includes(v)) return false
  return null
}

/**
 * Search the catalog: every whitespace-separated term must appear in the
 * entry; an exact id or name match sorts first. Filters that match nothing
 * yield an empty list rather than an error.
 */
export function searchFx(catalog, { query = '', category = '', loop = '', actor = null, limit = 20 } = {}) {
  let rows = catalog.entries
  const cat = fold(category).trim()
  if (cat) rows = rows.filter((entry) => fold(entry.id.split('/')[0]) === cat || fold(entry.categoryName) === cat)
  const wantLoop = loopWanted(loop)
  if (wantLoop !== null) rows = rows.filter((entry) => Boolean(entry.loop) === wantLoop)
  if (actor === true) rows = rows.filter((entry) => Boolean(entry.actor))
  else if (actor === false) rows = rows.filter((entry) => !entry.actor)
  const q = fold(query).trim()
  if (q) {
    const terms = q.split(/\s+/).filter(Boolean)
    rows = rows.filter((entry) => {
      const hay = haystack(entry)
      return terms.every((term) => hay.includes(term))
    })
    rows = rows.slice().sort((a, b) => {
      const rank = (entry) => (fold(entry.id) === q ? 0 : fold(entry.name) === q ? 1 : fold(entry.id).startsWith(q) ? 2 : 3)
      return rank(a) - rank(b) || fold(a.id).localeCompare(fold(b.id))
    })
  }
  return rows.slice(0, clampLimit(limit))
}

/** A random pick, optionally narrowed by category / loop / actor. */
export function randomFx(catalog, { category = '', loop = '', actor = null } = {}) {
  const pool = searchFx(catalog, { category, loop, actor, limit: catalog.entries.length || 1 })
  if (pool.length === 0) return null
  return pool[Math.floor(Math.random() * pool.length)]
}

/** Absolute path of one effect's source file ('' when the mirror is gone). */
export function fxSourcePath(entry) {
  if (!entry?.filePath) return ''
  return existsSync(entry.filePath) ? entry.filePath : ''
}

/** Absolute path of one effect's preview PNG ('' when it was never rendered). */
export function fxPreviewPath(entry) {
  if (!entry?.previewPath) return ''
  return existsSync(entry.previewPath) ? entry.previewPath : ''
}

/** Source text, verbatim (caller decides how much to print). */
export function readFxSource(entry) {
  const file = fxSourcePath(entry)
  if (!file) throw new Error(`effect ${entry?.id ?? '?'} has no source file in the mirror`)
  return readFileSync(file, 'utf8')
}

/** Import list of an effect, so a caller can tell what it pulls from core. */
export function fxImports(entry) {
  let text = ''
  try {
    text = readFxSource(entry)
  } catch {
    return { core: [], lib: false }
  }
  const core = []
  for (const line of text.split('\n')) {
    if (!/^import\s/.test(line)) continue
    if (line.includes('core/index.js')) {
      const match = line.match(/\{([^}]*)\}/)
      if (match) core.push(...match[1].split(',').map((part) => part.trim().split(/\s+as\s+/)[0]).filter(Boolean))
    }
  }
  return { core: [...new Set(core)], lib: /from\s+"\.\/_lib\.js"/.test(text) }
}

/** Distribution over the whole catalog, for anim_fx_stats. */
export function fxStats(catalog) {
  const sizes = catalog.entries.map((entry) => entry.size[0] * entry.size[1])
  const byCategory = catalog.categories.map((row) => ({
    ...row,
    acted: catalog.entries.filter((entry) => entry.category === row.id && entry.act).length,
    loops: catalog.entries.filter((entry) => entry.category === row.id && entry.loop).length,
  }))
  const withPreview = catalog.entries.filter((entry) => fxPreviewPath(entry)).length
  return {
    total: catalog.total,
    categories: byCategory,
    acted: catalog.entries.filter((entry) => entry.act).length,
    loops: catalog.entries.filter((entry) => entry.loop).length,
    oneShots: catalog.entries.filter((entry) => !entry.loop).length,
    withActor: catalog.entries.filter((entry) => entry.actor).length,
    withPreview,
    missingSource: catalog.entries.filter((entry) => !fxSourcePath(entry)).length,
    pixels: {
      min: sizes.length > 0 ? Math.min(...sizes) : 0,
      max: sizes.length > 0 ? Math.max(...sizes) : 0,
      average: sizes.length > 0 ? Math.round(sizes.reduce((sum, n) => sum + n, 0) / sizes.length) : 0,
    },
    repo: catalog.repo,
    commit: catalog.commitShort || catalog.commit,
    upstream: catalog.upstream,
    generated: catalog.generated,
    version: catalog.version,
    license: catalog.license,
  }
}

/** The core files an export needs, relative to the mirror root. */
const CORE_GLOB = join('src', 'core')

/** Copy a directory of flat files (`src/core` has no subdirectories). */
function copyFlat(fromDir, toDir, want = () => true) {
  const made = []
  if (!existsSync(fromDir)) return made
  mkdirSync(toDir, { recursive: true })
  for (const file of readdirSync(fromDir)) {
    if (!want(file)) continue
    const from = join(fromDir, file)
    if (!statSync(from).isFile()) continue
    const to = join(toDir, file)
    copyFileSync(from, to)
    made.push(to)
  }
  return made
}

function copyOne(from, to) {
  if (!existsSync(from)) return ''
  mkdirSync(dirname(to), { recursive: true })
  copyFileSync(from, to)
  return to
}

const EXPORT_README = `# PixelFX export — 可直接运行的像素特效

这份目录由 dsh-anim-pack 的 \`anim_fx_export\` 从
[patch-gg/pixelfx](https://github.com/patch-gg/pixelfx)（MIT）复制而来，只含用到的部分：

    src/core/               引擎：两套缓冲（color + light）、Painter、sim、rig/act
    src/fx/<分类>/<特效>.js  特效本体（含同分类共用的 _lib.js）
    tools/render.mjs        渲染工具：接触表 / 逐帧 PNG
    tools/lib/fxlib.mjs     渲染用的辅助函数
    tools/lib/png.mjs       零依赖 PNG 编码器

不需要 npm install，直接跑：

    node tools/render.mjs fire/torch --zoom 2        # 接触表 records/fire/torch/contact.png
    node tools/render.mjs fire/torch --sheet         # 精灵表 PNG + Aseprite 风格 JSON
    node tools/render.mjs --help

在游戏里用时（浏览器 / canvas / Phaser / PixiJS / 任何 JS 引擎）：

    import { createFrame, clearFrame, createFx, composite } from './src/core/index.js'
    import * as torch from './src/fx/fire/torch.js'

    const frame = createFrame(320, 180)
    const img = new ImageData(320, 180)
    const fx = createFx(torch, { x: 160, y: 140 })

非 JS 引擎（Godot / Unity / GameMaker / LÖVE）走精灵表：
\`node tools/render.mjs <id> --sheet\` 写出的 PNG + JSON（帧矩形、时长、pivot）可以直接导入。

许可：代码与特效 MIT（© 2026 rehan-remade；sim.js 等改编自 Hugo Duprez / Sprite Fusion 的
pixel-art-vfx，act.js 改编自 Hollow Crown，均为 MIT）。详见本目录 LICENSE 与 NOTICE.md。
`

/**
 * Copy effects (plus the runtime they need) into `dir` as a runnable project.
 * Refuses to write into the mirror or into the plugin's own assets.
 */
export function exportFx(catalog, entries, { dir, runtime = true } = {}) {
  const target = resolve(dir)
  const inside = (base) => base && (target === base || target.startsWith(base + sep))
  if (inside(catalog.repo)) {
    return { ok: false, error: `refusing to export into the pixelfx mirror: ${target}`, files: [], ids: [] }
  }
  if (inside(catalog.root)) {
    return { ok: false, error: `refusing to export inside the plugin: ${target}`, files: [], ids: [] }
  }
  const files = []
  const ids = []
  try {
    mkdirSync(target, { recursive: true })
    if (runtime) {
      files.push(...copyFlat(join(catalog.repo, CORE_GLOB), join(target, 'src', 'core'), (file) => file.endsWith('.js')))
      for (const rel of [join('tools', 'render.mjs'), join('tools', 'lib', 'fxlib.mjs'), join('tools', 'lib', 'png.mjs')]) {
        const made = copyOne(join(catalog.repo, rel), join(target, rel))
        if (made) files.push(made)
      }
      for (const rel of ['LICENSE', 'NOTICE.md']) {
        const made = copyOne(join(catalog.repo, rel), join(target, rel))
        if (made) files.push(made)
      }
      const readme = join(target, 'README.md')
      if (!existsSync(readme)) {
        writeFileSync(readme, EXPORT_README)
        files.push(readme)
      }
      const pkg = join(target, 'package.json')
      if (!existsSync(pkg)) {
        writeFileSync(pkg, `${JSON.stringify({ name: 'pixelfx-export', private: true, type: 'module' }, void 0, 2)}\n`)
        files.push(pkg)
      }
    }
    for (const entry of entries) {
      const source = fxSourcePath(entry)
      if (!source) {
        ids.push({ id: entry.id, ok: false, error: 'source file missing in the mirror — rerun tools/build-fx.mjs' })
        continue
      }
      const rel = entry.file
      const made = copyOne(source, join(target, rel))
      if (made) files.push(made)
      if (entry.lib && entry.libPath && existsSync(entry.libPath)) {
        const libMade = copyOne(entry.libPath, join(target, dirname(rel), entry.lib))
        if (libMade) files.push(libMade)
      }
      ids.push({ id: entry.id, ok: true, name: entry.name, file: join(target, rel) })
    }
    return { ok: ids.every((row) => row.ok), dir: target, ids, files }
  } catch (error) {
    return { ok: false, error: String(error?.message ?? error), dir: target, ids, files }
  }
}

/** A ready-to-paste usage snippet for one effect. */
export function fxUsage(entry, { importPath = './src/core/index.js' } = {}) {
  const slug = String(entry.id.split('/').pop() ?? '').replace(/-([a-z])/g, (_, ch) => ch.toUpperCase())
  const [w, h] = entry.size
  return [
    `import { createFrame, clearFrame, createFx, composite } from '${importPath}'`,
    `import * as ${slug} from './src/fx/${entry.id}.js'`,
    '',
    `const frame = createFrame(${w}, ${h})          // ${w}×${h}`,
    `const img = new ImageData(${w}, ${h})`,
    `const fx = createFx(${slug}, { x: ${entry.origin[0]}, y: ${entry.origin[1]} })${entry.loop ? '  // loops' : '  // one-shot'}`,
    '',
    'function tick(dt) {',
    '  fx.update(dt)',
    '  clearFrame(frame)',
    '  fx.draw(frame, "back")',
    '  // draw your characters here',
    '  fx.draw(frame, "front")',
    '  composite(frame, img.data, "#12111a")',
    '  ctx.putImageData(img, 0, 0)',
    '}',
  ].join('\n')
}
